import { chromium } from 'playwright';
import { PNG } from 'pngjs';
const [,, w, h, qs=''] = process.argv;
const b = await chromium.launch({ args:['--use-angle=swiftshader','--enable-unsafe-swiftshader','--ignore-gpu-blocklist'] });
const p = await b.newPage({ viewport:{width:+w,height:+h} });
await p.goto('http://127.0.0.1:5174/m.html?'+qs);
await p.waitForFunction(()=>window.ready);
for (const t of [0.5, 3.2, 5, 8, 11]) {
  await p.evaluate(t=>window.st.seek(t), t);
  await p.waitForTimeout(150);
  const png = PNG.sync.read(await p.screenshot());
  let x0=1e9,y0=1e9,x1=-1,y1=-1, cx0=1e9,cy0=1e9,cx1=-1,cy1=-1;
  for (let y=0;y<png.height;y++) for (let x=0;x<png.width;x++){
    const i=(y*png.width+x)*4, r=png.data[i],g=png.data[i+1],bl=png.data[i+2];
    const d=Math.abs(r-0xF5)+Math.abs(g-0xEC)+Math.abs(bl-0xD9);
    if (d>40){ x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y); }
